function formatSessionDay(date) {
  return new Intl.DateTimeFormat("en-GB", {
    weekday: "short",
    day: "numeric",
    month: "short",
    year: "numeric",
  }).format(date);
}

function generateSessionDays(startDate, endDate, weekdays) {
  if (!startDate || !endDate) return [];
  const start = new Date(`${startDate}T12:00:00`);
  const end = new Date(`${endDate}T12:00:00`);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || start > end) return [];
  const allowed = new Set(weekdays.length ? weekdays : ["1", "2", "3", "4", "5"]);
  const days = [];
  for (const cursor = new Date(start); cursor <= end; cursor.setDate(cursor.getDate() + 1)) {
    if (cursor >= today && allowed.has(String(cursor.getDay()))) {
      days.push(formatSessionDay(cursor));
    }
  }
  return days;
}

function sessionBlockKey(block, index = 0) {
  return block.id || `${block.label || "session"}-${block.start || ""}-${block.end || ""}-${index}`;
}

function normaliseSessionBlocks(session, day = "") {
  const dayBlocks = day && Array.isArray(session?.dayBlocks?.[day]) ? session.dayBlocks[day] : null;
  const blocks = dayBlocks?.length
    ? dayBlocks
    : Array.isArray(session?.sessionBlocks) && session.sessionBlocks.length
    ? session.sessionBlocks
    : [{
        label: session?.title || "Session",
        start: String(session?.time || "").split("-")[0]?.trim() || "",
        end: String(session?.time || "").split("-")[1]?.trim() || "",
        price: Number(session?.price || 0),
      }];
  return blocks.map((block, index) => ({
    ...block,
    key: sessionBlockKey(block, index),
    label: block.label || `${block.start || "Start"}-${block.end || "End"}`,
    price: Number(block.price || 0),
  }));
}

function liveHolidayCampCatalog(rows = []) {
  const groups = new Map();
  rows.forEach((row) => {
    const key = `${row.siteName}::${row.campName}`;
    if (!groups.has(key)) {
      groups.set(key, {
        id: `live-camp-${safeDomId(key)}`,
        site: row.siteName,
        area: row.area || "London and Surrey",
        type: "Holiday Camp",
        title: row.campName || "Holiday Camp",
        academicYear: "live",
        days: [],
        dayBlocks: {},
        sessionBlocks: [],
        time: "",
        price: Number(row.pricing?.dayPrice || row.price || 0),
        capacity: Number(row.capacity || 0),
        paymentRoute: "PonchoPay card + vouchers",
        ageRange: row.ageRange || "",
        eligibility: row.eligibility || {},
        pricing: row.pricing || {},
        imageUrl: row.presentation?.imageUrl || "",
        campType: row.presentation?.campType || "Multi-Activity",
        dayPresentation: {},
        features: ["Book individual days", "Full-week saving applied automatically", "Early Drop-Off available per day"],
      });
    }
    const camp = groups.get(key);
    const day = formatSessionDay(new Date(`${row.sessionDate}T12:00:00`));
    const start = new Date(row.startsAt).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
    const end = new Date(row.endsAt).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
    const block = {
      id: row.sessionBlockId,
      sessionBlockId: row.sessionBlockId,
      liveSessionId: row.sessionId,
      label: row.blockLabel || "Holiday Camp",
      start,
      end,
      price: Number(row.price || 0),
      capacity: Number(row.capacity || 0),
    };
    camp.days.push(day);
    camp.dayPresentation[day] = {
      imageUrl: row.presentation?.imageUrl || camp.imageUrl || "",
      campType: row.presentation?.campType || camp.campType || "Multi-Activity",
      notes: row.presentation?.notes || "",
    };
    if (!camp.dayBlocks[day]) camp.dayBlocks[day] = [];
    camp.dayBlocks[day].push(block);
    camp.dayBlocks[day].sort((a, b) => a.start.localeCompare(b.start));
    if (block.label === "Holiday Camp") {
      camp.time = `${start}-${end}`;
      camp.price = Number(row.price || camp.price || 0);
    }
    camp.capacity = Math.min(camp.capacity, Number(row.capacity || 0));
  });
  return [...groups.values()].map((camp) => {
    const days = [...new Set(camp.days)];
    return { ...camp, days, sessionBlocks: camp.dayBlocks[days[0]] || [] };
  });
}

function parentActivityLabel(session) {
  const title = String(session?.title || session?.activity || "");
  const type = String(session?.type || "");
  if (/holiday camp|camp/i.test(`${type} ${title}`)) return "Camp";
  if (/breakfast/i.test(title)) return "Breakfast";
  if (/after[-\s]?school/i.test(title)) return "After school";
  return title || "Care";
}

function parentActivityChoiceLabel(session) {
  if (session?.type === "Holiday Camp" && session?.academicYear === "live") {
    return session.title || "Holiday Camp";
  }
  return parentActivityLabel(session);
}

function pricingServiceKeyForSession(session) {
  const label = `${session?.type || ""} ${session?.title || ""} ${parentActivityLabel(session)}`.toLowerCase();
  if (label.includes("breakfast")) return "breakfast_club";
  if (label.includes("after school") || label.includes("after-school")) return "after_school_club";
  if (label.includes("holiday") || label.includes("camp")) return "holiday_club";
  if (label.includes("activity")) return "activity_club";
  return label.replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "") || "other";
}

function pricingBenefitForSession(session, pricing) {
  if (!pricing || !session) return null;
  const normalisePlace = (value) => String(value || "").toLowerCase().replace(/school|prep|the|[^a-z0-9]/g, "");
  const serviceKey = pricingServiceKeyForSession(session);
  const siteKey = normalisePlace(session.site);
  const normaliseActivity = (value) => String(value || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  const activityName = normaliseActivity(session.title || parentActivityLabel(session));
  const candidates = [...(pricing.overrides || []), ...(pricing.benefits || [])];
  return candidates.find((benefit) => {
    const schoolKey = normalisePlace(benefit.school);
    const serviceMatches = !benefit.serviceKey || benefit.serviceKey === "all" || benefit.serviceKey === serviceKey;
    const schoolMatches = !schoolKey || siteKey.includes(schoolKey) || schoolKey.includes(siteKey);
    const benefitActivity = normaliseActivity(benefit.activity);
    const activityMatches = !benefitActivity || activityName.includes(benefitActivity) || benefitActivity.includes(activityName);
    return serviceMatches && schoolMatches && activityMatches && benefit.discountType !== "no_discount" && Number(benefit.discountValue || 0) >= 0;
  }) || null;
}

function priceAfterBenefit(price, benefit) {
  const base = Number(price || 0);
  if (!benefit) return base;
  if (benefit.discountType === "free_session") return 0;
  if (benefit.discountType === "percentage") return Math.max(0, base * (1 - Number(benefit.discountValue || 0) / 100));
  if (benefit.discountType === "fixed_amount") return Math.max(0, base - Number(benefit.discountValue || 0));
  if (benefit.discountType === "fixed_price") return Math.max(0, Number(benefit.discountValue || 0));
  return base;
}

function pricingBenefitLabel(benefit) {
  if (!benefit) return "";
  if (benefit.discountType === "free_session") return "Free";
  if (benefit.discountType === "percentage") return `${Number(benefit.discountValue || 0)}% off`;
  if (benefit.discountType === "fixed_amount") return `${money(benefit.discountValue)} off`;
  if (benefit.discountType === "fixed_price") return `${money(benefit.discountValue)} fixed price`;
  return benefit.name || "Pricing benefit";
}

function parentActivityRank(session) {
  const label = parentActivityLabel(session);
  if (label === "After school") return 1;
  if (label === "Breakfast") return 2;
  if (label === "Camp") return 3;
  return 4;
}

function isUuid(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value || ""));
}

function sessionBlockIdForBooking(block) {
  return block.sessionBlockId || block.session_block_id || block.id || "";
}

function basketPricingSignatureForItems(items = []) {
  return items.map((item) => `${item.sessionBlockId}:${item.childId}`).sort().join("|");
}

async function resolveLiveBasketSessionBlocks(items = []) {
  if (!items.length || items.every((item) => isUuid(item.sessionBlockId))) return items;
  const basketDates = items.map((item) => item.sessionDate || labDayIso(item.day)).filter(Boolean).sort();
  const firstDate = basketDates[0];
  const lastDate = basketDates.at(-1);
  const siteName = items.find((item) => item.site)?.site || "";
  if (!firstDate || !lastDate) throw new Error("A basket session is missing its date. Remove it and add it again.");
  const liveSessions = await fetchBookableSessions({
    from: new Date(`${firstDate}T00:00:00`),
    to: new Date(`${lastDate}T23:59:59`),
    siteName,
    limit: 1000,
  });
  return items.map((item) => {
    if (isUuid(item.sessionBlockId)) return item;
    const sessionDate = item.sessionDate || labDayIso(item.day);
    const matchingSessions = liveSessions.filter((session) => (
      String(session.site?.name || "").trim().toLowerCase() === String(item.site || "").trim().toLowerCase()
      && String(session.startsAt || "").slice(0, 10) === sessionDate
    ));
    const liveSession = matchingSessions.find((session) => session.blocks?.some((block) => (
      String(block.label || "").trim().toLowerCase() === String(item.sessionLabel || "").trim().toLowerCase()
    )));
    const liveBlock = liveSession?.blocks?.find((block) => (
      String(block.label || "").trim().toLowerCase() === String(item.sessionLabel || "").trim().toLowerCase()
    ));
    if (!liveBlock?.id) {
      throw new Error(`${item.site || "This site"} ${item.sessionLabel || "session"} on ${sessionDate || "the selected date"} is not available for live booking.`);
    }
    return { ...item, liveSessionId: liveSession.id, sessionBlockId: liveBlock.id };
  });
}

function preferredParentSession(sessionList) {
  return [...sessionList].sort((a, b) => parentActivityRank(a) - parentActivityRank(b) || String(a.time || "").localeCompare(String(b.time || "")))[0];
}

function bookingBlockRows(draft) {
  if (Array.isArray(draft?.dayBreakdown) && draft.dayBreakdown.length) {
    return draft.dayBreakdown.map((row) => {
      const blocks = Array.isArray(row.blocks) && row.blocks.length
        ? row.blocks
        : [{ label: row.time || "Session", start: "", end: "", price: row.price }];
      return {
        day: row.day,
        time: row.time || blocks.map((block) => `${block.start || ""}-${block.end || ""}`.replace(/^-|-$/g, "")).filter(Boolean).join(", "),
        price: Number(row.price || blocks.reduce((sum, block) => sum + Number(block.price || 0), 0)),
        blocks: blocks.map((block) => ({
          label: block.label || `${block.start || ""}-${block.end || ""}`.replace(/^-|-$/g, "") || "Session",
          start: block.start || "",
          end: block.end || "",
          price: Number(block.price || 0),
        })),
      };
    });
  }
  return (draft?.days || []).map((day) => ({
    day,
    time: draft?.time || "",
    price: Number(draft?.total || 0) / Math.max(1, (draft?.days || []).length),
    blocks: [{ label: draft?.time || "Session", start: "", end: "", price: 0 }],
  }));
}

function bookingBlockCount(draft) {
  return bookingBlockRows(draft).reduce((sum, row) => sum + row.blocks.length, 0);
}

function bookingBlockSummary(draft, limit = 2) {
  const rows = bookingBlockRows(draft);
  if (!rows.length) return "No sessions selected";
  const visible = rows.slice(0, limit).map((row) => {
    const times = row.blocks.map((block) => `${block.start}-${block.end}`.replace(/^-|-$/g, "") || block.label).join(", ");
    return `${row.day}${times ? `: ${times}` : ""}`;
  });
  return rows.length > limit ? `${visible.join(" · ")} + ${rows.length - limit} more day${rows.length - limit === 1 ? "" : "s"}` : visible.join(" · ");
}

function bookingBlockReceiptLines(draft) {
  return bookingBlockRows(draft).flatMap((row) => [
    `${row.day}${row.time ? ` (${row.time})` : ""}`,
    ...row.blocks.map((block) => `  - ${block.label}${block.start || block.end ? ` ${block.start}-${block.end}` : ""}${block.price ? ` ${money(block.price)}` : ""}`),
  ]);
}

function bookingRowStart(row) {
  const day = parseLabDay(row.day);
  if (!day) return null;
  const timeText = row.time || row.blocks?.[0]?.start || "";
  const match = String(timeText).match(/(\d{1,2}):(\d{2})/);
  if (match) day.setHours(Number(match[1]), Number(match[2]), 0, 0);
  return day;
}

function activeBookingItemStatus(status) {
  return ["reserved", "confirmed", "waitlist", "attended"].includes(String(status || "").toLowerCase());
}

function bookingItemDate(item) {
  const metadata = item?.metadata || {};
  return metadata.sessionDate || String(item?.startsAt || item?.starts_at || "").slice(0, 10);
}

function bookingItemLabel(item) {
  const metadata = item?.metadata || {};
  return metadata.labBlockLabel || item?.sessionLabel || item?.session_label || "";
}

function bookingItemChildName(item) {
  return item?.childName || item?.child_name || "";
}

function bookingPolicyState(draft, hours = 24) {
  const starts = bookingBlockRows(draft)
    .map(bookingRowStart)
    .filter(Boolean)
    .sort((a, b) => a.getTime() - b.getTime());
  const firstStart = starts[0] || null;
  const windowHours = Math.max(0, Number(hours || 0));
  if (!firstStart) {
    return {
      allowed: false,
      label: "Date check needed",
      detail: "This booking has no valid session start date.",
      firstStart: null,
      deadline: null,
    };
  }
  const deadline = new Date(firstStart.getTime() - windowHours * 60 * 60 * 1000);
  const now = new Date();
  const allowed = now <= deadline;
  const sessionLabel = `${firstStart.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" })} ${firstStart.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" })}`;
  const deadlineLabel = deadline.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }) + " " + deadline.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
  return {
    allowed,
    label: allowed ? `${windowHours}h window open` : "Outside policy window",
    detail: allowed ? `Changes close ${deadlineLabel}. First session starts ${sessionLabel}.` : `Changes closed ${deadlineLabel}. First session starts ${sessionLabel}.`,
    firstStart,
    deadline,
  };
}

function parseLabDay(value) {
  if (!value) return null;
  const cleaned = String(value).replace(/,/g, "").trim();
  const currentYear = new Date().getFullYear();
  const withYear = /\b\d{4}\b/.test(cleaned) ? cleaned : `${cleaned} ${currentYear}`;
  const parsed = new Date(`${withYear} 12:00:00`);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function labDayIso(value) {
  const parsed = parseLabDay(value);
  return parsed ? parsed.toISOString().slice(0, 10) : "";
}

function campCatalogDateRange(days = []) {
  const dates = days.map(parseLabDay).filter(Boolean).sort((a, b) => a - b);
  if (!dates.length) return "Dates coming soon";
  const first = dates[0];
  const last = dates[dates.length - 1];
  const sameMonth = first.getMonth() === last.getMonth() && first.getFullYear() === last.getFullYear();
  const firstLabel = first.toLocaleDateString("en-GB", {
    day: "numeric",
    ...(sameMonth ? {} : { month: "short" }),
    ...(first.getFullYear() === last.getFullYear() ? {} : { year: "numeric" }),
  });
  const lastLabel = last.toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" });
  return dates.length === 1 ? lastLabel : `${firstLabel}–${lastLabel}`;
}

function canonicalSessionDays(session, proposedDays = []) {
  const days = Array.isArray(proposedDays) ? proposedDays : [];
  if (session?.academicYear !== "2026/27") return days;
  const calendarKey = schoolCalendarKeyForSite(session?.site);
  if (!calendarKey) return [];
  if (session?.type === "Holiday Camp") {
    const candidates = campCandidatePeriods(calendarKey);
    return days.filter((day) => {
      const date = labDayIso(day);
      return date && candidates.some((period) => date >= period.start && date <= period.end);
    });
  }
  const windows = teachingWindows(calendarKey);
  const blocked = blockingPeriods(calendarKey).filter((period) => period.end);
  return days.filter((day) => {
    const date = labDayIso(day);
    const insideTeaching = date && windows.some((window) => date >= window.start && date <= window.end);
    const isBlocked = date && blocked.some((period) => date >= period.start && date <= period.end);
    return insideTeaching && !isBlocked;
  });
}

function safeDomId(value) {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "item";
}

function generateParentTemporaryPassword() {
  const suffix = Math.random().toString(36).slice(2, 8).toUpperCase();
  return `Apres-${suffix}-26!`;
}

function buildMonthlyPaymentSchedule(total, count, anchorDay, depositPercent = 0) {
  const amount = Math.max(0, Number(total || 0));
  if (!amount || count < 2) return [];
  const anchor = parseLabDay(anchorDay) || new Date();
  anchor.setHours(12, 0, 0, 0);
  const totalPennies = Math.round(amount * 100);
  const depositPennies = Math.min(totalPennies, Math.max(0, Math.round(totalPennies * (Number(depositPercent || 0) / 100))));
  const remainingPennies = Math.max(0, totalPennies - depositPennies);
  const splitCount = depositPennies > 0 ? count - 1 : count;
  const basePennies = splitCount ? Math.floor(remainingPennies / splitCount) : 0;
  const remainder = remainingPennies - (basePennies * splitCount);
  return Array.from({ length: count }, (_, index) => {
    const dueDate = new Date(anchor);
    dueDate.setMonth(anchor.getMonth() + index);
    dueDate.setDate(Math.min(anchor.getDate(), 28));
    const pennies = depositPennies > 0 && index === 0
      ? depositPennies
      : basePennies + (index === count - 1 ? remainder : 0);
    return {
      number: index + 1,
      dueDate: isoDate(dueDate),
      label: dueDate.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }),
      amount: pennies / 100,
      status: index === 0 ? (depositPennies > 0 ? "Deposit due at booking" : "Due at booking") : "Scheduled",
      routeStatus: "Awaiting PonchoPay mandate",
    };
  });
}

function isoDate(date) {
  return date.toISOString().slice(0, 10);
}

function normaliseChildDob(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const compactRaw = raw.replace(/\s+/g, "");
  const isoMatch = compactRaw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const ukMatch = compactRaw.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/);
  const compactUkMatch = compactRaw.match(/^(\d{2})(\d{2})(\d{4})$/);
  let year = "";
  let month = "";
  let day = "";
  if (isoMatch) {
    [, year, month, day] = isoMatch;
  } else if (ukMatch) {
    [, day, month, year] = ukMatch;
    day = day.padStart(2, "0");
    month = month.padStart(2, "0");
  } else if (compactUkMatch) {
    [, day, month, year] = compactUkMatch;
  } else {
    return "";
  }
  const parsed = new Date(`${year}-${month}-${day}T12:00:00`);
  const today = new Date();
  today.setHours(23, 59, 59, 999);
  if (
    Number.isNaN(parsed.getTime())
    || parsed.getFullYear() !== Number(year)
    || parsed.getMonth() + 1 !== Number(month)
    || parsed.getDate() !== Number(day)
    || parsed > today
  ) {
    return "";
  }
  return `${year}-${month}-${day}`;
}

function childDobParts(value) {
  const raw = String(value || "").trim();
  if (!raw) return { day: "", month: "", year: "" };
  const compactRaw = raw.replace(/\s+/g, "");
  const isoMatch = compactRaw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const ukMatch = compactRaw.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/);
  const compactUkMatch = compactRaw.match(/^(\d{2})(\d{2})(\d{4})$/);
  const partialUkMatch = compactRaw.match(/^(\d{0,2})\/(\d{0,2})\/(\d{0,4})$/);
  if (isoMatch) {
    const [, year, month, day] = isoMatch;
    return { day, month, year };
  }
  if (ukMatch) {
    const [, day, month, year] = ukMatch;
    return { day: day.padStart(2, "0"), month: month.padStart(2, "0"), year };
  }
  if (compactUkMatch) {
    const [, day, month, year] = compactUkMatch;
    return { day, month, year };
  }
  if (partialUkMatch) {
    const [, day, month, year] = partialUkMatch;
    return { day, month, year };
  }
  return { day: "", month: "", year: "" };
}

function childDobFromParts(parts) {
  const day = parts.day ? String(parts.day).padStart(2, "0") : "";
  const month = parts.month ? String(parts.month).padStart(2, "0") : "";
  const year = String(parts.year || "");
  if (!parts.day && !parts.month && !parts.year) return "";
  if (!parts.day || !parts.month || !parts.year) return `${day}/${month}/${year}`;
  const normalised = normaliseChildDob(`${day}/${month}/${year}`);
  return normalised || `${day}/${month}/${year}`;
}

function rangeFromPreset(mode, customStart, customEnd) {
  const today = new Date();
  today.setHours(12, 0, 0, 0);
  if (mode === "Week") {
    const start = new Date(today);
    const day = start.getDay() || 7;
    start.setDate(start.getDate() - day + 1);
    const end = new Date(start);
    end.setDate(start.getDate() + 6);
    return [isoDate(start), isoDate(end)];
  }
  if (mode === "Month") {
    return [isoDate(new Date(today.getFullYear(), today.getMonth(), 1, 12)), isoDate(new Date(today.getFullYear(), today.getMonth() + 1, 0, 12))];
  }
  if (mode === "Half-term") {
    return ["2026-06-01", "2026-07-24"];
  }
  if (mode === "Year") {
    return ["2026-06-01", "2027-05-31"];
  }
  return [customStart, customEnd];
}

