  function persistSavedQuotes(nextQuotes) {
    setSavedQuotes(nextQuotes);
    localStorage.setItem("apres-booking-lab-saved-quotes", JSON.stringify(nextQuotes));
  }

  function saveQuote(option = null) {
    const sourceSession = option?.session || activeSession;
    const sourceDates = option?.dates?.length ? option.dates : pickedDays;
    const sourceTotal = option ? option.total : total;
    if (!sourceDates.length) {
      setStatus("Choose at least one date before saving a quote.");
      return;
    }
    const quote = {
      id: `quote-${Date.now()}-${Math.random().toString(16).slice(2)}`,
      createdAt: new Date().toISOString(),
      sessionId: sourceSession.id,
      type: sourceSession.type,
      site: sourceSession.site,
      title: sourceSession.title,
      area: sourceSession.area,
      time: sourceSession.time,
      days: sourceDates,
      dayBreakdown: option
        ? (option.dayBreakdown || [])
        : pickedDayRows.map((row) => ({
            day: row.day,
            time: row.time,
            price: row.price,
            blocks: row.selectedBlocks.map((block) => ({
              label: block.label,
              start: block.start,
              end: block.end,
              price: block.price,
            })),
          })),
      children: selectedChildren.map((child) => child.name),
      childCount,
      addOns: option ? [] : availableAddOns.filter((item) => selectedAddOns.includes(item.id)).map((item) => item.label),
      total: sourceTotal,
      route: option?.route || activePaymentRoute,
      paymentPlan: option ? "Pay now" : activePaymentPlan,
      paymentSchedule: option ? [] : monthlyPaymentSchedule,
      availability: option?.availability || (isWaitlist ? "Waitlist likely" : `${remainingSpaces} spaces visible`),
      status: "Quote",
    };
    persistSavedQuotes([quote, ...savedQuotes.filter((item) => !(item.sessionId === quote.sessionId && item.days.join("|") === quote.days.join("|")))].slice(0, 8));
    setStatus(`${quote.type} quote saved to basket.`);
  }

  function loadSavedQuote(quote) {
    const session = sessions.find((item) => item.id === quote.sessionId);
    if (!session) {
      setStatus("That quote activity is no longer available.");
      return;
    }
    setCareType(session.type);
    setSelectedSchool(session.site);
    setArea(session.area);
    setQuery("");
    chooseSession(session);
    setSelectedDays((current) => ({ ...current, [session.id]: quote.days || [] }));
    if (Array.isArray(quote.dayBreakdown) && quote.dayBreakdown.length) {
      const sessionBlocks = normaliseSessionBlocks(session);
      setSelectedDayBlocks((current) => {
        const next = { ...current };
        quote.dayBreakdown.forEach((row) => {
          const matchingKeys = (row.blocks || [])
            .map((savedBlock) => sessionBlocks.find((block) => block.start === savedBlock.start && block.end === savedBlock.end)?.key)
            .filter(Boolean);
          if (row.day && matchingKeys.length) next[`${session.id}::${row.day}`] = matchingKeys;
        });
        return next;
      });
    }
    setSelectedAddOns(labAddOns.filter((item) => (quote.addOns || []).includes(item.label)).map((item) => item.id));
    setCheckoutStep("Review");
    setStatus(`${quote.type} quote loaded into checkout.`);
  }

  function removeSavedQuote(id) {
    persistSavedQuotes(savedQuotes.filter((quote) => quote.id !== id));
    setStatus("Quote removed from basket.");
  }

  function bookSavedQuotes() {
    if (!savedQuotes.length) {
      setStatus("Save at least one quote before booking saved options.");
      return;
    }
    const now = Date.now();
    const quoteBookings = savedQuotes.map((quote, index) => {
      const session = sessions.find((item) => item.id === quote.sessionId) || activeSession;
      const method = String(quote.route || "").includes("Invoice")
        ? "invoice"
        : String(quote.route || "").includes("vouchers first")
          ? "voucher"
          : "card";
      return {
        id: `lab-booking-${now}-${index}`,
        createdAt: new Date(now + index).toISOString(),
        quoteId: quote.id,
        sessionId: quote.sessionId,
        site: quote.site,
        activity: quote.title,
        days: quote.days || [],
        dayBreakdown: (quote.days || []).map((day) => ({
          day,
          time: quote.time || session.time,
          price: Number(quote.total || 0) / Math.max(1, Number(quote.childCount || 1) * Math.max(1, (quote.days || []).length)),
          capacity: session.capacity,
          paymentRoute: quote.route,
        })),
        children: quote.children || selectedChildren.map((child) => child.name),
        childCount: quote.childCount || childCount,
        addOns: quote.addOns || [],
        total: Number(quote.total || 0),
        paymentMethod: method,
        paymentLabel: labPaymentOptions.find(([value]) => value === method)?.[1] || method,
        paymentRoute: quote.route,
        paymentPlan: quote.paymentPlan || "Pay now",
        paymentSchedule: quote.paymentPlan === "Monthly" ? (quote.paymentSchedule || []) : [],
        paymentPlanStatus: quote.paymentPlan === "Monthly" ? "PonchoPay mandate pending" : "Pay in full",
        dueToday: quote.paymentPlan === "Monthly" ? Number(quote.paymentSchedule?.[0]?.amount || 0) : Number(quote.total || 0),
        outstandingBalance: quote.paymentPlan === "Monthly"
          ? Math.max(0, Number(quote.total || 0) - Number(quote.paymentSchedule?.[0]?.amount || 0))
          : method === "card" ? 0 : Number(quote.total || 0),
        invoiceStatus: quote.availability === "Waitlist likely"
          ? "Not issued until a place is confirmed"
          : quote.paymentPlan === "Monthly"
            ? "Payment plan invoice issued"
            : method === "card"
              ? "Paid receipt issued"
              : "Outstanding until PonchoPay matches the payment",
        paymentStatus: quote.availability === "Waitlist likely"
          ? "No payment taken"
          : quote.paymentPlan === "Monthly"
            ? "Mandate pending"
            : method === "card"
              ? "Paid in prototype"
              : "Awaiting auto reconciliation",
        paymentReference: "",
        promoCode: "",
        rulesSnapshot: rules,
        checkoutConfidence: {
          score: quote.availability === "Waitlist likely" ? 78 : 96,
          capacity: quote.availability,
          payment: quote.paymentPlan === "Monthly" ? "Instalments scheduled" : method === "card" ? "Card payment now" : `${quote.route} reference`,
          invoice: quote.paymentPlan === "Monthly" ? "Payment plan invoice" : method === "card" ? "Receipt after payment" : "Outstanding until reconciled",
          issues: quote.availability === "Waitlist likely" ? ["Quote may require waitlist confirmation."] : [],
        },
        parentName: activeFamily.parentName,
        parentEmail: activeFamily.email,
        childName: (quote.children || [])[0] || selectedChildren[0]?.name || "",
        collector: activeFamily.collectors?.[0] || activeFamily.parentName || "",
        emergencyPhone: activeFamily.phone || activeFamily.emergencyContact || "",
        medicalNotes: selectedChildren.flatMap((child) => child.flags || []).join(", "),
        consents: { terms: true, emergency: true, data: true },
        status: quote.availability === "Waitlist likely"
          ? "Waitlist"
          : quote.paymentPlan === "Monthly"
            ? "Payment plan active"
            : method === "card"
              ? "Prototype paid"
              : "Payment reference pending",
      };
    });
    persistDrafts([...quoteBookings, ...drafts].slice(0, 40));
    persistSavedQuotes([]);
    setConfirmation({
      id: `quote-batch-${now}`,
      batch: true,
      status: "Batch booked",
      children: savedQuoteChildren,
      site: `${savedQuotes.length} saved option${savedQuotes.length === 1 ? "" : "s"}`,
      activity: "Saved quote checkout",
      days: savedQuotes.flatMap((quote) => quote.days || []),
      total: savedQuoteTotal,
      paymentRoute: "Mixed saved quote routes",
      paymentLabel: "Mixed payment routes",
      paymentStatus: "Booked from saved quotes",
      invoiceStatus: "Invoice records created for each booking",
      dueToday: quoteBookings.reduce((sum, booking) => sum + Number(booking.dueToday || 0), 0),
      outstandingBalance: quoteBookings.reduce((sum, booking) => sum + Number(booking.outstandingBalance || 0), 0),
      parentEmail: activeFamily.email,
      bookings: quoteBookings,
    });
    addAuditLog("Saved quote basket booked", `${activeFamily.parentName} booked ${quoteBookings.length} saved quote${quoteBookings.length === 1 ? "" : "s"}.`);
    setStatus(`${quoteBookings.length} saved quote${quoteBookings.length === 1 ? "" : "s"} converted into bookings.`);
  }

