  function updatePaymentDraft(id, updater) {
    const nextDrafts = drafts.map((draft) => draft.id === id ? { ...updater(draft), updatedAt: new Date().toISOString() } : draft);
    persistDrafts(nextDrafts);
  }

  function setPaymentState(id, status, extras = {}) {
    updatePaymentDraft(id, (draft) => ({ ...draft, status, ...extras }));
    setActivePaymentId(id);
  }

  function simulateCardAction(id, outcome) {
    const draft = drafts.find((item) => item.id === id);
    if (!draft) return;
    if (outcome === "success") {
      setPaymentState(id, "Prototype paid", {
        paymentMethod: "card",
        paymentReference: draft.paymentReference || `pi_${Date.now()}`,
        reconciledAt: new Date().toISOString(),
        paymentTimeline: [
          ...(draft.paymentTimeline || []),
          { label: "Card intent succeeded", at: new Date().toISOString() },
        ],
      });
      setStatus("Card payment intent simulated as succeeded.");
      return;
    }
    setPaymentState(id, outcome === "failed" ? "Payment failed" : "Payment action required", {
      paymentMethod: "card",
      paymentReference: draft.paymentReference || `pi_${Date.now()}`,
      paymentTimeline: [
        ...(draft.paymentTimeline || []),
        { label: outcome === "failed" ? "Card declined" : "Strong customer authentication required", at: new Date().toISOString() },
      ],
    });
    setStatus(outcome === "failed" ? "Card payment simulated as failed." : "Card payment now requires parent action.");
  }

  function settledPaymentDraft(draft, { amount, label, eventType, payload } = {}) {
    const paidAmount = Math.max(0, Number(draft.total || 0), Number(amount ?? draft.outstandingBalance ?? draft.total ?? 0));
    const now = new Date().toISOString();
    const receiptNumber = draft.receiptNumber || `APR-${new Date().getFullYear()}-${String(Date.now()).slice(-8)}`;
    return {
      ...draft,
      status: "Prototype paid",
      paymentStatus: "Paid",
      invoiceStatus: "Paid receipt issued",
      receiptStatus: "Issued",
      receiptNumber,
      receivedAmount: paidAmount,
      outstandingBalance: 0,
      reconciledAt: now,
      receiptIssuedAt: now,
      mismatchReason: "",
      checkoutSessionStatus: "payment_completed",
      ponchoCheckout: draft.ponchoCheckout ? {
        ...draft.ponchoCheckout,
        status: "payment_completed",
        message: "PonchoPay completed callback cleared the invoice and issued the receipt.",
      } : draft.ponchoCheckout,
      paymentTimeline: [
        ...(draft.paymentTimeline || []),
        {
          label: label || "PonchoPay payment completed",
          at: now,
          eventType,
          payload,
          amount: paidAmount,
          receiptNumber,
        },
      ],
      updatedAt: now,
    };
  }

  function receiptMessageForDraft(draft, amount, source = "PonchoPay") {
    const paidAmount = Math.max(0, Number(amount ?? draft.receivedAmount ?? draft.total ?? 0));
    return {
      id: `parent-receipt-${draft.id}-${Date.now()}`,
      createdAt: new Date().toISOString(),
      template: "Payment receipt",
      channel: notificationChannelForEmail(draft.parentEmail || activeFamily.email, "invoices", "Email"),
      recipient: draft.parentEmail || activeFamily.email || "parent@example.com",
      bookingId: draft.id,
      subject: `Receipt ready · ${draft.activity}`,
      body: `Hi ${draft.parentName || activeFamily.parentName || "there"}, ${source} has confirmed payment for ${draft.activity}. Amount paid: ${money(paidAmount)}. Receipt: ${draft.receiptNumber || "available in the portal"}.`,
      status: "Sent",
    };
  }

  function simulatePonchoPayWebhook(id, eventType) {
    const draft = drafts.find((item) => item.id === id);
    const scenario = PONCHOPAY_SANDBOX_WEBHOOKS.find((item) => item.eventType === eventType);
    if (!draft || !scenario) return;
    const payload = buildPonchoPayWebhookPayload(draft, eventType);
    const now = new Date().toISOString();
    const expected = Math.max(0, Number(draft.total || 0) - (draft.creditEvents || []).reduce((sum, event) => sum + Number(event.amount || 0), 0));
    const mismatch = eventType === "payment_mismatch";
    const completed = eventType === "payment_completed";
    const failed = eventType === "payment_failed";
    if (completed) {
      const settledDraft = settledPaymentDraft({
        ...draft,
        paymentReference: draft.paymentReference || payload.providerReference,
      }, {
        amount: expected,
        label: `PonchoPay webhook: ${scenario.label}`,
        eventType,
        payload,
      });
      const nextDrafts = drafts.map((item) => item.id === id ? settledDraft : item);
      persistDrafts(nextDrafts);
      persistMessages([receiptMessageForDraft(settledDraft, expected, "PonchoPay"), ...messageLog].slice(0, 70));
    } else {
      setPaymentState(id, scenario.resultStatus, {
        paymentReference: draft.paymentReference || payload.providerReference,
        receivedAmount: mismatch ? payload.amount : draft.receivedAmount,
        reconciledAt: draft.reconciledAt || "",
        paymentStatus: eventType === "payment_captured" ? "Payment captured" : eventType === "payment_reported_complete" ? "Awaiting PonchoPay match" : failed ? "Payment failed" : draft.paymentStatus,
        invoiceStatus: eventType === "payment_captured" ? "Booking confirmed; payment captured" : eventType === "payment_reported_complete" ? "Payment reported; awaiting match" : failed ? "Payment failed; action needed" : draft.invoiceStatus,
        mismatchReason: mismatch ? `PonchoPay sandbox mismatch: received ${money(payload.amount)} against ${money(payload.expectedAmount)}.` : draft.mismatchReason || "",
        paymentTimeline: [
          ...(draft.paymentTimeline || []),
          { label: `PonchoPay webhook: ${scenario.label}`, at: now, eventId: payload.eventId, eventType, payload },
        ],
      });
    }
    recordGovernanceEvent(`PonchoPay webhook ${scenario.label}`, `${draft.parentName || "Parent"} · ${draft.activity} · ${money(Number(draft.total || 0))}`, {
      category: "Payments",
      risk: failed || mismatch ? "High" : completed ? "Medium" : "Low",
      approvalRequired: failed || mismatch,
      reason: approvalReason,
    });
    setStatus(`Sandbox webhook applied: ${scenario.label}. Parent state: ${scenario.parentState}.`);
  }

  function replayLastPonchoPayWebhook(id) {
    const draft = drafts.find((item) => item.id === id);
    if (!draft) return;
    const lastWebhook = [...(draft.paymentTimeline || [])].reverse().find((event) => event.payload?.eventId || event.eventId);
    if (!lastWebhook) {
      setStatus("No webhook event is available to replay for this invoice.");
      return;
    }
    const providerEventId = lastWebhook.payload?.eventId || lastWebhook.providerEventId || lastWebhook.eventId;
    updatePaymentDraft(id, (item) => ({
      ...item,
      paymentTimeline: [
        ...(item.paymentTimeline || []),
        {
          label: `PonchoPay webhook ignored: duplicate ${lastWebhook.eventType || "event"}`,
          at: new Date().toISOString(),
          auditEventId: `duplicate-${providerEventId}-${Date.now()}`,
          eventId: providerEventId,
          providerEventId,
          eventType: lastWebhook.eventType || "duplicate_webhook",
          duplicateOf: providerEventId,
          ignored: true,
          payload: lastWebhook.payload || { eventId: providerEventId },
        },
      ],
    }));
    recordGovernanceEvent("PonchoPay duplicate webhook ignored", `${draft.parentName || "Parent"} · ${draft.activity} · ${providerEventId}`, {
      category: "Payments",
      risk: "Low",
      approvalRequired: false,
      reason: "Idempotency replay check",
    });
    setActivePaymentId(id);
    setStatus("Duplicate webhook replay ignored safely. Invoice state was not changed.");
  }

