  function messagePaymentMethodLabel(draft) {
    if (draft.paymentMethod === "tfc" || draft.paymentMethod === "tax-free") return "Tax-Free Childcare";
    if (draft.paymentMethod === "voucher") return "childcare voucher";
    if (draft.paymentMethod === "invoice") return "invoice";
    return "card";
  }

  function messageFor(draft, template) {
    const parent = draft.parentName || "there";
    const children = draft.children?.join(", ") || draft.childName || "your child";
    const sessions = bookingBlockSummary(draft, 3) || (draft.days || []).join(", ") || "the selected sessions";
    const methodLabel = messagePaymentMethodLabel(draft);
    if (template === "Payment reminder") {
      return `Hi ${parent}, your ${draft.activity} booking at ${draft.site} is reserved. Please complete payment or add your voucher/TFC reference within ${rules.paymentDueHours} hours so PonchoPay can reconcile it automatically. The invoice remains visible in your parent portal until it clears.`;
    }
    if (template === "Payment reference" || template === "Payment reference saved") {
      return `Hi ${parent}, your ${methodLabel} reference has been saved for ${draft.activity}. Your booking is confirmed while PonchoPay matches the payment automatically. We will issue the receipt when it clears.`;
    }
    if (template === "Card payment failed") {
      return `Hi ${parent}, your card payment for ${draft.activity} did not complete. Your booking is still visible in the parent portal, and you can retry the payment or choose another available route.`;
    }
    if (template === "Invoice ready") {
      return `Hi ${parent}, your invoice for ${draft.activity} is ready in the parent portal. Sessions: ${sessions}. Amount due: ${money(Number(draft.total || 0))}. Payment route: ${draft.paymentRoute || "PonchoPay"}.`;
    }
    if (template === "Booking change") {
      return `Hi ${parent}, your ${draft.activity} booking has been updated. Sessions now showing: ${sessions}. Your parent portal shows the latest balance, credit or additional amount due.`;
    }
    if (template === "Cancellation confirmation") {
      return `Hi ${parent}, your ${draft.activity} booking has been cancelled under the current policy. Any credit or balance change is visible in your parent portal.`;
    }
    if (template === "Incident follow-up") {
      return `Hi ${parent}, we have added a care note for ${children}. A member of the team can talk this through at collection.`;
    }
    if (template === "Missing info") {
      return `Hi ${parent}, please check your booking details for ${draft.activity}. We still need complete collection, emergency or medical information before the session.`;
    }
    return `Hi ${parent}, your ${draft.activity} booking at ${draft.site} is confirmed for ${(draft.days || []).join(", ")}. Your parent portal shows the sessions, invoice status and payment route. Total: ${money(Number(draft.total || 0))}.`;
  }

  function sendLabMessage(draft, template) {
    const message = {
      id: `lab-message-${Date.now()}`,
      createdAt: new Date().toISOString(),
      template,
      recipient: draft.parentEmail || "parent@example.com",
      bookingId: draft.id,
      subject: `${template} · ${draft.activity}`,
      body: messageFor(draft, template),
    };
    persistMessages([message, ...messageLog].slice(0, 30));
  }

