  function saveStagingCredentialIntake(event) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const projectRef = String(form.get("projectRef") || "").trim();
    const functionsUrl = String(form.get("functionsUrl") || "").trim();
    const next = {
      projectRef,
      functionsUrl,
      frontendEnv: {
        VITE_SUPABASE_URL: Boolean(projectRef || form.get("VITE_SUPABASE_URL")),
        VITE_SUPABASE_ANON_KEY: Boolean(form.get("VITE_SUPABASE_ANON_KEY")),
      },
      supabaseSecrets: {
        APRES_SERVICE_ROLE_KEY: Boolean(form.get("APRES_SERVICE_ROLE_KEY")),
        PONCHOPAY_API_URL: Boolean(form.get("PONCHOPAY_API_URL")),
        PONCHOPAY_INTEGRATION_KEY: Boolean(form.get("PONCHOPAY_INTEGRATION_KEY")),
        PONCHOPAY_PROCESSOR_TOKEN: Boolean(form.get("PONCHOPAY_PROCESSOR_TOKEN")),
      },
      updatedAt: new Date().toISOString(),
    };
    setStagingCredentials(next);
    localStorage.setItem("apres-booking-lab-staging-credentials", JSON.stringify(next));
    addAuditLog("Staging credentials intake updated", `${Object.values(next.frontendEnv).filter(Boolean).length}/2 frontend values and ${Object.values(next.supabaseSecrets).filter(Boolean).length}/4 server secrets marked present. Secret values were not stored.`);
    setStatus("Staging credential checklist updated. Secret values were not saved in the browser.");
  }

