  async function copyStagingDeployText(label, text) {
    try {
      if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(text);
      } else {
        const textarea = document.createElement("textarea");
        textarea.value = text;
        textarea.setAttribute("readonly", "readonly");
        textarea.style.position = "fixed";
        textarea.style.left = "-9999px";
        document.body.appendChild(textarea);
        textarea.select();
        const copied = document.execCommand("copy");
        document.body.removeChild(textarea);
        if (!copied) throw new Error("Clipboard copy unavailable");
      }
      setStatus(`${label} copied to clipboard.`);
    } catch {
      downloadTextFile(`apres-${label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}.txt`, text);
      setStatus(`${label} downloaded because clipboard access was unavailable.`);
    }
  }

